(window.webpackJsonp=window.webpackJsonp||[]).push([[608],{940:function(t,e,s){"use strict";s.r(e);var r=s(33),n=Object(r.a)({},function(){var t=this,e=t.$createElement,s=t._self._c||e;return s("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[s("h1",{attrs:{id:"svetsfel-specifika-problem-vid-tig-svetsning"}},[s("a",{staticClass:"header-anchor",attrs:{href:"#svetsfel-specifika-problem-vid-tig-svetsning","aria-hidden":"true"}},[t._v("#")]),t._v(" Svetsfel & specifika problem vid TIG-svetsning")]),t._v(" "),s("p",[s("img",{attrs:{src:"https://proxy.itslearning.com/image/v1?u=https%3a%2f%2flernia.itslearning.com%2fdata%2f1821%2fC2568%2fTeori%2520k%25c3%25a4lsvets%25201%2fST%25201%2fST+1+bild+11.JPG&s=4f8d40b4f10745a1a8182f376a020437&h=EJ64jFxvr0M3EJM%2fjH4%2bzJZXgfpOr7uM5t4o7vLIux4%3d",alt:""}}),t._v("De svetsfel som kan drabba en TIG-svetsare är i stort sett desamma som kan inträffa vid svetsning med andra metoder.")]),t._v(" "),s("p",[t._v("Dock finns speciella risker vid just TIG-svetsning. I likhet med alla andra gasbågsvetsmetoder är risken för porer ganska stor om gasskyddet uteblir. Det är därför av största vikt att slangar, anslutningar etc är i bästa kondition, att gaskåpan är väl rengjord, att inte drag eller andra luftströmmar för bort skyddsgasen samt inte minst; att gasflaskan är öppen och att rätt gasflöde är inställt.")]),t._v(" "),s("p",[t._v("Då TIG-svetsningen ofta utförs i t.ex. rostfritt stål är risken för krymphåligheter (pipes) i svetsens avslutning ganska stor. För att eliminera risken för krymphåligheter, använd alltid svetsströmkällans slopefunktion.")]),t._v(" "),s("p",[t._v("De flesta TIG-svetsströmkällor idag är försedda med s.k. slopefunktioner; slope-up resp. slope-down.")]),t._v(" "),s("p",[t._v("Normalt när man tänder en ljusbåge tänds den momentant, dvs. direkt. Vid TIG-svetsning kan det innebära för snabb uppvärmning av elektroden med risk för att stänk av volframelektroden hamnar i svetsen.")]),t._v(" "),s("p",[s("img",{attrs:{src:"https://proxy.itslearning.com/image/v1?u=https%3a%2f%2flernia.itslearning.com%2fdata%2f1821%2fC2568%2fTeori%2520k%25c3%25a4lsvets%25201%2fST%25201%2fST+1+bild+12.JPG&s=6b455de4a9394ef9b84f7e71b27cc7d5&h=WnXJZ4qoEojWSxCLgO7pmYFMzF5EUJVV9ImFp%2f%2bwzyI%3d",alt:""}}),t._v("Vid slope-up stiger strömmen sakta så att elektroden förvärms och risken för volfram i svetsen minimeras. Ytterligare ger slope up funktionen möjlighet för svetsaren att hitta igen svetsstället innan full ström går på.")]),t._v(" "),s("p",[t._v("Slope down - funktionen kan ställas så att strömmen långsamt tonar bort vilket ger långsam avsvalning.")]),t._v(" "),s("p",[t._v("Slope-down funktionen är ger svetsaren en möjlighet att tillföra svetsgods undertiden värmen minskar på elektroden. Det ska leda till att pipes ej ska uppstå. Slope-downtiden väljs utifrån den strömstyrka som är inställd och det grundmaterial som svetsas på. Rostfritt och aluminium har lättare för att få pipes, vilket kräver längre slope-downtid.")]),t._v(" "),s("p",[t._v("Riskerna för att få volframinneslutning i svetsen är också stora om man valt för hög ström i förhållande till elektrodens dimension.")])])},[],!1,null,null,null);e.default=n.exports}}]);